{"path": "/app/bin/hourly.py", "content": "#!/usr/bin/env python3
"""Hourly station product from logger dumps. See /app/docs.

Usage: python3 hourly.py INPUT_DIR OUTPUT_FILE
"""
import json
import math
import os
import re
import sys
from datetime import datetime, timezone

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {
    "temp": (-50.0, 60.0),
    "rh": (0.0, 100.0),
    "pres": (870.0, 1085.0),
    "wspd": (0.0, 60.0),
    "wdir": (0.0, 360.0),
    "rain": (0.0, 5000.0),
}
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING_NUM = re.compile(r"^-9999(\.0*)?$")
TIME_RE = re.compile(r"^(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d):(\d\d)$")
SYNC_LOGGER = re.compile(r"logger=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)")
SYNC_REF = re.compile(r"ref=(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)")


def epoch(y, mo, d, h, mi, s):
    return int(datetime(y, mo, d, h, mi, s, tzinfo=timezone.utc).timestamp())


def parse_time(text):
    m = TIME_RE.match(text.strip())
    if not m:
        return None
    return epoch(*(int(g) for g in m.groups()))


def parse_tz(text):
    text = text.strip()
    if text == "Z":
        return 0
    sign = -1 if text[0] == "-" else 1
    hh, mm = text[1:].split(":")
    return sign * (int(hh) * 3600 + int(mm) * 60)


def converter(quantity, unit):
    """Return function value->canonical value, or None for unknown unit."""
    if quantity == "temp":
        if unit == "degC":
            return lambda v: v
        if unit == "degF":
            return lambda v: (v - 32) * 5 / 9
        if unit == "K":
            return lambda v: v - 273.15
    elif quantity == "rh":
        if unit == "pct":
            return lambda v: v
        if unit == "frac":
            return lambda v: v * 100
    elif quantity == "pres":
        if unit == "hPa":
            return lambda v: v
        if unit == "kPa":
            return lambda v: v * 10
        if unit == "inHg":
            return lambda v: v * 33.8638866667
        if unit == "mmHg":
            return lambda v: v * 1.33322387415
    elif quantity == "wspd":
        if unit == "ms":
            return lambda v: v
        if unit == "kmh":
            return lambda v: v / 3.6
        if unit == "kn":
            return lambda v: v * 1852 / 3600
        if unit == "mph":
            return lambda v: v * 0.44704
    elif quantity == "wdir":
        if unit == "deg":
            return lambda v: v
    elif quantity == "rain":
        if unit == "mm":
            return lambda v: v
        if unit.startswith("tips:"):
            s = float(unit[5:])
            return lambda v: v * s
    return None


def canonical_unit(quantity):
    return {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms",
            "wdir": "deg", "rain": "mm"}[quantity]


def parse_value(field):
    f = field.strip()
    if f == "" or f == "---" or f.lower() == "nan" or MISSING_NUM.match(f):
        return None
    try:
        v = float(f)
    except ValueError:
        return None
    if math.isnan(v):
        return None
    return v


def read_dump(path):
    """Return dict with station, upload, interval, rows, syncs."""
    with open(path, "rb") as fh:
        raw = fh.read()
    text = raw.decode("utf-8", errors="replace")
    if text.startswith("\ufeff"):
        text = text[1:]
    info = {"station": None, "upload": None, "interval": None,
            "rows": [], "syncs": []}
    tz = 0
    columns = None
    units = {q: canonical_unit(q) for q in QUANTITIES}
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, value = m.group(1), m.group(2).strip()
            if key == "station":
                info["station"] = value
            elif key == "upload":
                info["upload"] = int(value)
            elif key == "interval":
                info["interval"] = int(float(value))
            elif key == "tz":
                tz = parse_tz(value)
            elif key == "columns":
                columns = [c.strip() for c in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        q, u = pair.split("=", 1)
                        units[q] = u
            elif key == "sync":
                ml = SYNC_LOGGER.search(value)
                mr = SYNC_REF.search(value)
                if ml and mr:
                    lt = parse_time(ml.group(1))
                    ref = parse_time(mr.group(1).rstrip("Z"))
                    t = lt - tz
                    info["syncs"].append((t, ref - t))
            continue
        if columns is None:
            continue
        fields = line.split(",")
        if len(fields) != len(columns):
            continue
        rec = dict(zip(columns, fields))
        if "time" not in rec:
            continue
        lt = parse_time(rec["time"])
        if lt is None:
            continue
        vals = {}
        for q in QUANTITIES:
            if q not in rec:
                continue
            v = parse_value(rec[q])
            if v is None:
                continue
            conv = converter(q, units.get(q, canonical_unit(q)))
            if conv is None:
                continue
            v = conv(v)
            lo, hi = RANGES[q]
            if v != v or v < lo or v > hi:
                continue
            vals[q] = v
        info["rows"].append((lt - tz, vals))
    return info


def offset_at(t, syncs):
    """syncs: sorted list of (t, offset)."""
    if not syncs:
        return 0
    if t <= syncs[0][0]:
        return syncs[0][1]
    if t >= syncs[-1][0]:
        return syncs[-1][1]
    lo, hi = 0, len(syncs) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if syncs[mid][0] <= t:
            lo = mid
        else:
            hi = mid
    t1, o1 = syncs[lo]
    t2, o2 = syncs[hi]
    if t == t1:
        return o1
    return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)


def fmt_hour(h_end):
    return datetime.fromtimestamp(h_end, tz=timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")


def build_station(station, dumps):
    interval = dumps[0]["interval"]
    # sync points: dedupe by logger UTC instant, largest upload wins
    sync_map = {}
    for d in dumps:
        for t, off in d["syncs"]:
            cur = sync_map.get(t)
            if cur is None or d["upload"] > cur[0]:
                sync_map[t] = (d["upload"], off)
    syncs = sorted((t, v[1]) for t, v in sync_map.items())
    # rows: dedupe by logger UTC instant, largest upload wins
    row_map = {}
    for d in dumps:
        for t, vals in d["rows"]:
            cur = row_map.get(t)
            if cur is None or d["upload"] > cur[0]:
                row_map[t] = (d["upload"], vals)
    if not row_map:
        return None
    rows = []
    for t, (_, vals) in row_map.items():
        c = t + offset_at(t, syncs)
        rows.append((c, t, vals))
    rows.sort(key=lambda r: (r[0], r[1]))

    def hour_end(c):
        return -((-c) // 3600) * 3600

    first = hour_end(rows[0][0])
    last = hour_end(rows[-1][0])
    expected = 3600 // interval

    n = {}
    sums = {}
    vec = {}
    rain_inc = {}
    prev_rain = None
    for c, t, vals in rows:
        h = hour_end(c)
        for q in QUANTITIES:
            if q in vals:
                n[(h, q)] = n.get((h, q), 0) + 1
        for q in ("temp", "rh", "pres", "wspd"):
            if q in vals:
                sums[(h, q)] = sums.get((h, q), 0.0) + vals[q]
        if "wdir" in vals and "wspd" in vals and vals["wspd"] > 0:
            a = math.radians(vals["wdir"])
            s = vec.get(h, (0.0, 0.0))
            vec[h] = (s[0] + math.sin(a), s[1] + math.cos(a))
        if "rain" in vals:
            r = vals["rain"]
            if prev_rain is not None and (c - prev_rain[0]) * 2 <= 5 * interval:
                p = prev_rain[1]
                inc = r - p if r >= p else r
                rain_inc[h] = rain_inc.get(h, 0.0) + inc
            prev_rain = (c, r)

    hours = []
    h = first
    while h <= last:
        entry = {"hour": fmt_hour(h)}
        for q in QUANTITIES:
            cnt = n.get((h, q), 0)
            ok = cnt * 4 >= expected * 3
            value = None
            if ok and cnt > 0:
                if q in ("temp", "rh", "pres", "wspd"):
                    value = round(sums[(h, q)] / cnt, 2)
                elif q == "wdir":
                    if h in vec:
                        sx, sy = vec[h]
                        if math.hypot(sx, sy) > 1e-9:
                            deg = math.degrees(math.atan2(sx, sy)) % 360.0
                            value = round(deg, 2)
                            if value >= 360:
                                value = 0.0
                elif q == "rain":
                    value = round(rain_inc.get(h, 0.0), 2)
                    if value == 0:
                        value = 0.0
            elif ok and cnt == 0 and expected == 0:
                value = None
            entry[q] = {"value": value, "n": cnt}
        hours.append(entry)
        h += 3600
    return {"station": station, "interval_s": interval, "hours": hours}


def main(argv):
    in_dir, out_file = argv[1], argv[2]
    names = sorted(f for f in os.listdir(in_dir)
                   if f.endswith(".log") and os.path.isfile(os.path.join(in_dir, f)))
    by_station = {}
    for name in names:
        d = read_dump(os.path.join(in_dir, name))
        if d["station"] is None:
            continue
        by_station.setdefault(d["station"], []).append(d)
    stations = []
    for sid in sorted(by_station):
        s = build_station(sid, by_station[sid])
        if s is not None:
            stations.append(s)
    with open(out_file, "w", encoding="utf-8") as fh:
        json.dump({"stations": stations}, fh, indent=1)
        fh.write("\n")


if __name__ == "__main__":
    main(sys.argv)
"}
